<?php
namespace App\Services\Operations;
use App\Models\{Folio,MinibarConsumption,MinibarRoomItem,Stay,Store};use App\Services\Folios\FolioService;use App\Services\Procurement\StoreStockService;use Illuminate\Support\Facades\DB;use RuntimeException;
class MinibarService{
 public function __construct(private StoreStockService $stock,private FolioService $folios){}
 public function consume(Stay $stay,MinibarRoomItem $roomItem,float $qty,int $userId):MinibarConsumption{return DB::transaction(function()use($stay,$roomItem,$qty,$userId){if($qty<=0)throw new RuntimeException('Quantity must be greater than zero.');if($roomItem->room_id!==$stay->room_id)throw new RuntimeException('Mini-bar item does not belong to this room.');$folio=Folio::where('stay_id',$stay->id)->where('status','open')->first();if(!$folio)throw new RuntimeException('No open guest folio exists for this stay.');$price=(float)$roomItem->selling_price;$consumption=MinibarConsumption::create(['property_id'=>$stay->property_id,'room_id'=>$stay->room_id,'stay_id'=>$stay->id,'folio_id'=>$folio->id,'minibar_room_item_id'=>$roomItem->id,'quantity'=>$qty,'unit_price'=>$price,'total'=>$qty*$price,'recorded_by'=>$userId,'recorded_at'=>now()]);if($roomItem->store_id){$this->stock->move(Store::findOrFail($roomItem->store_id),$roomItem->inventoryItem,-$qty,'minibar',$userId,'Mini-bar consumption',$consumption,null,'MB-'.$consumption->id);$consumption->update(['stock_posted'=>true]);}$this->folios->addCharge($folio,['department'=>'minibar','description'=>'Mini-bar: '.$roomItem->inventoryItem->name,'quantity'=>$qty,'unit_price'=>$price,'tax_amount'=>0],$userId);$consumption->update(['folio_posted'=>true]);return $consumption->fresh();});}
}
